    ("code", "const form = document.querySelector('#order');\nconst email = form.elements.email;\nconst error = document.querySelector('#email-error');\n\nemail.addEventListener('input', () => {\n  if (email.validity.typeMismatch) {\n    email.setCustomValidity('Please enter an address like name@example.com');\n  } else {\n    email.setCustomValidity('');\n  }\n  error.textContent = email.validationMessage;   // live message, also read by screen readers via aria-live\n});\n\nform.addEventListener('submit', async e => {\n  e.preventDefault();\n  if (!form.reportValidity()) return;\n  const data = Object.fromEntries(new FormData(form));\n  const button = form.querySelector('button');\n  button.disabled = true;\n  try {\n    const res = await fetch('/api/order', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });\n    if (!res.ok) throw new Error('Server error');\n    form.hidden = true;\n    document.querySelector('#thanks').hidden = false;\n  } catch (err) {\n    error.textContent = 'Could not send. Please try again.';\n  } finally {\n    button.disabled = false;\n  }\n});"),
