    ("code", "// books.json  (served by a local server, e.g. python -m http.server)\n// [ { \"id\": 1, \"title\": \"Learn HTML\", \"price\": 120 }, ... ]\n\nasync function loadBooks() {\n  const cached = localStorage.getItem('books');\n  if (cached) return JSON.parse(cached);\n  const res = await fetch('books.json');\n  const books = await res.json();\n  localStorage.setItem('books', JSON.stringify(books));\n  return books;\n}\n\nloadBooks().then(render).catch(() => {\n  document.querySelector('#list').textContent = 'Could not load the catalogue.';\n});\n\n// Reading the query string: books.html?tag=css\nconst tag = new URLSearchParams(location.search).get('tag');\nif (tag) render(books.filter(b => b.tags.includes(tag)));"),
