    ("code", "// Accessible disclosure button (menu, accordion, 'read more')\nconst button = document.querySelector('#menu-button');\nconst menu = document.querySelector('#menu');\n\nfunction setOpen(open) {\n  button.setAttribute('aria-expanded', String(open));\n  menu.hidden = !open;\n  if (open) menu.querySelector('a')?.focus();\n}\nbutton.addEventListener('click', () => setOpen(button.getAttribute('aria-expanded') !== 'true'));\ndocument.addEventListener('keydown', e => { if (e.key === 'Escape') { setOpen(false); button.focus(); } });\ndocument.addEventListener('click', e => { if (!menu.contains(e.target) && e.target !== button) setOpen(false); });"),
