    ("p", "Combine the lessons: a catalogue page that loads books from JSON, filters as you type, sorts by price, adds items to a cart stored in localStorage, and shows the total. The full code is in the projects that follow this lesson."),
    ("code", "// Outline of app.js\nconst state = { books: [], query: '', sort: 'title', cart: JSON.parse(localStorage.getItem('cart')) ?? [] };\n\nfunction visibleBooks() {\n  return state.books\n    .filter(b => b.title.toLowerCase().includes(state.query))\n    .sort((a, b) => state.sort === 'price' ? a.price - b.price : a.title.localeCompare(b.title));\n}\nfunction render() { renderList(visibleBooks()); renderCart(); }\nfunction save() { localStorage.setItem('cart', JSON.stringify(state.cart)); }\n\nsearch.addEventListener('input', e => { state.query = e.target.value.toLowerCase(); render(); });\nsortSelect.addEventListener('change', e => { state.sort = e.target.value; render(); });\nlist.addEventListener('click', e => {\n  const id = Number(e.target.closest('[data-id]')?.dataset.id);\n  if (e.target.matches('.add')) { state.cart.push(id); save(); render(); }\n});\n\nloadBooks().then(books => { state.books = books; render(); });"),
